export default function manifest(): MetadataRoute.Manifest {
  return {
    name: string,
    short_name: string,
    description: string,
    start_url: string,
    display: "standalone" | "fullscreen" | "minimal-ui" | "browser",
    background_color: string,
    theme_color: string,
    icons: Array<{
      src: string,
      sizes: string,
      type: string,
      purpose?: "any" | "maskable" | "monochrome"
    }>
  }
}

export const metadata: Metadata = {
  title: string | Template,
  description: string,
  // Additional metadata fields available but not required for Story 1.4
}
